// SPDX-License-Identifier: Apache-2.0
pragma solidity >=0.8.22 <0.9.0;
import "../lib/Types.sol";
contract WireProbe is Base {
    uint256 constant SIZE = 1 + 2;
    event Complex(Outer data, Price price, Peer peer, Choice choice, function(uint256) external returns(bool) callback, bytes32[SIZE][] grid);
    event Changed(address indexed who, uint256 value);
    event Changed(uint32 indexed who, bytes32 value);
    event Hidden(uint256 indexed id, address value) anonymous;
    function emitAll() external { emit Left.Same(1); emit Right.Same(2); emit Left.Remote(msg.sender, 3); }
}
abstract contract AbstractEvents { event AbstractOnly(uint8 value); }
interface InterfaceEvents { event InterfaceOnly(bool value); }
library LibraryEvents { event LibraryOnly(bytes value); }
contract EmptyEvents {}

