// SPDX-License-Identifier: Apache-2.0
pragma solidity >=0.8.22 <0.9.0;
library Left { event Same(uint256 value); event Remote(address indexed actor, uint32 value); }
library Right { event Same(uint256 value); }
interface Base { event Inherited(bytes32 indexed key); }
contract Peer {}
type Price is uint128;
enum Choice { First, Second, Third }
struct Inner { uint32 count; string note; }
struct Outer { Inner inner; Inner[2][] list; }
